mapper.select:
SELECT VDATE, PROFIT_TYPE
FROM FIN_PRODUCT
where FINPROD_ID = #{finprodId}

SELECT distinct a.PORTFOLIO_ID FROM
PTL_TRADE a left join STL_PAY_ORDERS b on a.BUSI_ID = b.ORDER_ID
where b.ORDER_ID=#{orderId}

mapper.update:
UPDATE PTL_SEC_POSITION SET AMOUNT = AMOUNT - #{amount}
WHERE PORTFOLIO_ID = #{portfolioId}
    AND SEC_ACCT_ID = #{secAcctId}
    AND FINPROD_ID = #{finprodId}
    AND BRANCH = #{branch}
    AND INV_AIM = #{invAim}
    AND HODING_TYPE = #{hodingType}
    AND CDATE = #{cdate}

UPDATE PTL_CASH_POSITION SET AMOUNT = AMOUNT - #{amount}
WHERE PORTFOLIO_ID = #{portfolioId}
     AND ACCT_ID = #{acctId}
     AND HODING_TYPE = #{hodingType}
     AND CDATE = #{cdate}
     AND CCY = #{ccy}

mapper.select:
SELECT PPD.DIS_PERCENT, PPD.PORTFOLIO_ID FROM PTL_PORTFOLIO PT
left join PTL_PORTFOLIO_DIS PPD ON PT.PORTFOLIO_ID = PPD.PORTFOLIO_ID
WHERE PARENT_PORTFOLIO_ID = #{portfolioId}

select T3.PAY_TYPE from FIN_PRODUCT T
LEFT JOIN FIN_PRODUCT_ADD T3 ON T3.FINPROD_ID = T.FINPROD_ID
where T.finprod_id=#{chlId,jdbcType=VARCHAR}
